//! Independently authored extended Python expectations, never regenerated by Rust.

use fabric_cli_context::*;
use serde_json::{Value, json};
use std::{
    cell::RefCell,
    collections::{BTreeMap, VecDeque},
    sync::Arc,
};

const FIXTURE: &str = include_str!("../../../tests/compatibility/context/extended_cases.json");

fn text<'a>(record: &'a Value, field: &str) -> &'a str {
    record[field]
        .as_str()
        .unwrap_or_else(|| panic!("missing {field}: {record}"))
}

fn workspace_kind(value: &str) -> VirtualWorkspaceKind {
    VirtualWorkspaceKind::ALL
        .into_iter()
        .find(|kind| kind.collection() == value || kind.suffix() == value)
        .unwrap()
}
fn item_kind(value: &str) -> VirtualItemKind {
    VirtualItemKind::ALL
        .into_iter()
        .find(|kind| kind.collection() == value || kind.suffix() == value)
        .unwrap()
}
fn onelake_kind(value: &str) -> OneLakeKind {
    match value {
        "FOLDER" => OneLakeKind::Folder,
        "FILE" => OneLakeKind::File,
        "TABLE" => OneLakeKind::Table,
        "SHORTCUT" => OneLakeKind::Shortcut,
        "UNDEFINED" => OneLakeKind::Undefined,
        _ => panic!("unknown OneLake fixture type {value}"),
    }
}

fn graph(fixture: &Value) -> (BTreeMap<String, Arc<PathElement>>, HierarchyCatalog) {
    let mut nodes = BTreeMap::<String, Arc<PathElement>>::new();
    let mut core = Vec::new();
    let mut virtuals = Vec::new();
    for record in fixture["catalog"].as_array().unwrap() {
        let name = text(record, "name");
        let id = record["id"].as_str().map(str::to_owned);
        let kind = text(record, "kind");
        let node = if kind == "Tenant" {
            PathElement::from_fabric(Element::tenant(name, id.unwrap()))
        } else {
            let parent = &nodes[text(record, "parent")];
            let extended = match kind {
                "Workspace" => None,
                "Item" => None,
                "VirtualWorkspace" => Some(PathKind::VirtualWorkspace(workspace_kind(name))),
                "VirtualWorkspaceItem" => Some(PathKind::VirtualWorkspaceItem(workspace_kind(
                    text(record, "type"),
                ))),
                "VirtualItemContainer" => Some(PathKind::VirtualItemContainer(item_kind(name))),
                "VirtualItem" => Some(PathKind::VirtualItem(item_kind(text(record, "type")))),
                "OneLakeItem" => Some(PathKind::OneLake(onelake_kind(text(record, "subtype")))),
                _ => panic!("unknown fixture kind {kind}"),
            };
            if let Some(kind) = extended {
                PathElement::child(name, id, kind, Arc::clone(parent)).unwrap()
            } else {
                let kind = if kind == "Workspace" {
                    NodeKind::Workspace(match text(record, "type") {
                        "Workspace" => WorkspaceType::Workspace,
                        "Personal" => WorkspaceType::Personal,
                        _ => panic!("unexpected workspace type"),
                    })
                } else {
                    NodeKind::Item(ItemType::parse(text(record, "type")).unwrap())
                };
                let element =
                    Element::child(name, id, kind, Arc::clone(parent.fabric().unwrap())).unwrap();
                core.push(Arc::clone(&element));
                PathElement::from_fabric(element)
            }
        };
        if matches!(
            node.kind(),
            PathKind::VirtualItem(_) | PathKind::VirtualWorkspaceItem(_)
        ) {
            virtuals.push(Arc::clone(&node));
        }
        assert!(nodes.insert(text(record, "key").into(), node).is_none());
    }
    (
        nodes,
        HierarchyCatalog::new(Catalog::new(core), virtuals, Vec::new()),
    )
}

fn snapshot(node: &PathElement) -> Value {
    let mut value = json!({ "path": node.path(), "path_id": node.path_id(), "kind": node.kind().as_str(), "name": node.name(), "id": node.id() });
    let subtype = match node.kind() {
        PathKind::Fabric(NodeKind::Workspace(kind)) => Some(kind.as_str()),
        PathKind::Fabric(NodeKind::Item(kind)) => Some(kind.as_str()),
        PathKind::VirtualWorkspace(kind) => Some(kind.collection()),
        PathKind::VirtualWorkspaceItem(kind) => Some(kind.suffix()),
        PathKind::VirtualItemContainer(kind) => Some(kind.collection()),
        PathKind::VirtualItem(kind) => Some(kind.suffix()),
        PathKind::OneLake(kind) => {
            value["local_path"] = json!(node.local_path());
            value["root_folder"] = json!(node.root_folder());
            Some(kind.as_str())
        }
        _ => None,
    };
    if let Some(subtype) = subtype {
        value["subtype"] = json!(subtype);
    }
    value
}

fn source_error(value: &Value) -> ContextError {
    let code = value["code"]
        .as_str()
        .filter(|value| !value.is_empty())
        .unwrap_or("UnknownError");
    let message = value["message"]
        .as_str()
        .filter(|value| !value.is_empty())
        .unwrap_or("An error occurred while processing the operation")
        .trim_end_matches('.');
    ContextError::lookup(code, message)
}

struct Boundary<'a> {
    catalog: &'a HierarchyCatalog,
    case: &'a Value,
    calls: RefCell<Vec<Value>>,
    properties: RefCell<VecDeque<Value>>,
    local: RefCell<VecDeque<Value>>,
}

impl Boundary<'_> {
    fn call(&self, call: Value) -> Result<(), ContextError> {
        self.calls.borrow_mut().push(call.clone());
        if let Some(failures) = self.case["failures"].as_array()
            && let Some(failure) = failures.iter().find(|failure| {
                ["op", "parent", "name"]
                    .iter()
                    .all(|key| failure[key] == call[key])
            })
        {
            return Err(source_error(&failure["error"]));
        }
        Ok(())
    }
    fn metadata(&self, call: Value) -> bool {
        self.calls.borrow_mut().push(call.clone());
        let mut response = self
            .local
            .borrow_mut()
            .pop_front()
            .expect("unscripted filesystem metadata request");
        let result = response
            .as_object_mut()
            .unwrap()
            .remove("result")
            .unwrap()
            .as_bool()
            .unwrap();
        assert_eq!(call, response, "caller filesystem operation");
        result
    }
}

impl Lookup for Boundary<'_> {
    fn lookup(&self, request: LookupRequest<'_>) -> Result<Option<String>, ContextError> {
        let op = match request.kind {
            LookupKind::Workspace => "workspace",
            LookupKind::Folder => "folder",
            LookupKind::NestedFolder => "nested_folder",
            LookupKind::Item => "item",
        };
        self.call(json!({ "op": op, "parent": request.parent.path(), "name": request.name }))?;
        self.catalog.lookup(request)
    }
}

impl HierarchyLookup for Boundary<'_> {
    fn virtual_id(
        &self,
        request: VirtualLookupRequest<'_>,
    ) -> Result<Option<String>, ContextError> {
        let op = match request.kind {
            PathKind::VirtualWorkspaceItem(kind) => match kind {
                VirtualWorkspaceKind::Capacity => "capacity",
                VirtualWorkspaceKind::Domain => "domain",
                VirtualWorkspaceKind::Connection => "connection",
                VirtualWorkspaceKind::Gateway => "gateway",
            },
            PathKind::VirtualItem(kind) => match kind {
                VirtualItemKind::SparkPool => "spark_pool",
                VirtualItemKind::ManagedIdentity => "managed_identity",
                VirtualItemKind::ManagedPrivateEndpoint => "managed_private_endpoint",
                VirtualItemKind::ExternalDataShare => "external_data_share",
            },
            _ => panic!("invalid virtual fixture request"),
        };
        self.call(json!({ "op": op, "parent": request.parent.path(), "name": request.name }))?;
        if request.kind == PathKind::VirtualItem(VirtualItemKind::ExternalDataShare) {
            // This is the caller mem-store boundary, not production path logic.
            // Source EDS lookup first resolves the encoded item before its shares.
            let item_name = request.name.rsplit_once('_').map_or("", |(item, _)| item);
            let workspace = request.parent.parent().unwrap().fabric().unwrap();
            let id = self.lookup(LookupRequest {
                kind: LookupKind::Item,
                parent: workspace,
                name: item_name,
            })?;
            if id.is_none() {
                return Err(ContextError::lookup(
                    "NotFound",
                    format!("The Item '{item_name}' could not be found"),
                ));
            }
        }
        self.catalog.virtual_id(request)
    }
    fn properties(&self, path: &str) -> Result<Option<OneLakeProperties>, ContextError> {
        self.calls
            .borrow_mut()
            .push(json!({ "op": "properties", "path": path }));
        let response = self
            .properties
            .borrow_mut()
            .pop_front()
            .expect("unscripted OneLake properties request");
        assert_eq!(response["path"], path);
        if response.get("error").is_some() {
            return Err(source_error(&response["error"]));
        }
        Ok(Some(OneLakeProperties {
            status_code: u16::try_from(response["status_code"].as_u64().unwrap()).unwrap(),
            resource_type: response["headers"]["x-ms-resource-type"]
                .as_str()
                .map(str::to_owned),
            is_shortcut: response["headers"]["x-ms-onelake-shortcut-path"] == "true",
        }))
    }
}

fn local_split(path: &str, windows: bool) -> (&str, &str) {
    // Pure caller OS-mode adapter for this bounded fixture, never Fabric paths.
    match path.rfind(|ch| ch == '/' || (windows && ch == '\\')) {
        Some(0) => (&path[..1], &path[1..]),
        Some(index) => (&path[..index], &path[index + 1..]),
        None => ("", path),
    }
}

impl LocalLookup for Boundary<'_> {
    fn exists(&self, probe: LocalProbe<'_>) -> Result<bool, ContextError> {
        let arg = match probe {
            LocalProbe::Path(path) => json!(path),
            LocalProbe::Boolean(value) => json!(value),
        };
        Ok(self.metadata(json!({ "op": "exists", "arg": arg })))
    }
    fn access(&self, path: &str, mode: LocalAccess) -> Result<bool, ContextError> {
        Ok(self.metadata(json!({ "op": "access", "arg": path, "mode": match mode { LocalAccess::Read => "R_OK", LocalAccess::Write => "W_OK" } })))
    }
    fn dirname(&self, path: &str) -> Result<String, ContextError> {
        self.calls
            .borrow_mut()
            .push(json!({ "op": "dirname", "arg": path }));
        Ok(local_split(path, self.case["local_mode"] == "windows")
            .0
            .into())
    }
    fn describe(&self, path: &str) -> Result<LocalMetadata, ContextError> {
        let name = local_split(path, self.case["local_mode"] == "windows").1;
        Ok(LocalMetadata {
            path: path.into(),
            name: name.into(),
            id: self.case["local_fs"]["hash"]
                .as_i64()
                .expect("caller local identity must be explicit")
                .to_string(),
            kind: LocalKind::Other,
        })
    }
}

#[test]
fn extended_actual_source_expectations_match_all_observables_and_immutable_context() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    assert_eq!(fixture["schema_version"], 1);
    assert_eq!(
        fixture["source_commit"],
        "cf67fd52ea8b47e24c725e73d792de6f4a08e2e4"
    );
    let (nodes, catalog) = graph(&fixture);
    let before: BTreeMap<_, _> = nodes
        .iter()
        .map(|(key, node)| (key, snapshot(node)))
        .collect();
    let parents: BTreeMap<_, _> = nodes
        .iter()
        .map(|(key, node)| (key, node.parent().cloned()))
        .collect();
    let cases = fixture["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 93);
    for authored in cases {
        let mut case = fixture["defaults"].clone();
        case.as_object_mut()
            .unwrap()
            .extend(authored.as_object().unwrap().clone());
        let name = text(&case, "name");
        let boundary = Boundary {
            catalog: &catalog,
            case: &case,
            calls: RefCell::new(Vec::new()),
            properties: RefCell::new(
                case["properties"]
                    .as_array()
                    .cloned()
                    .unwrap_or_default()
                    .into(),
            ),
            local: RefCell::new(
                case["local_fs"]["operations"]
                    .as_array()
                    .cloned()
                    .unwrap_or_default()
                    .into(),
            ),
        };
        let key = text(&case, "current");
        let current = &nodes[key];
        assert_eq!(
            snapshot(current),
            fixture["current_snapshots"][key],
            "{name}: authored current snapshot"
        );
        let home = case["home"]
            .as_str()
            .map(|value| HomeContext::Workspace(value.into()))
            .unwrap_or_else(|| HomeContext::Unavailable(source_error(&case["home"]["error"])));
        let resolver = PathResolver::new(
            &boundary,
            Arc::clone(current),
            home,
            if case["local_mode"] == "windows" {
                "dir"
            } else {
                "ls"
            },
        )
        .unwrap()
        .with_local(&boundary);
        let tokens: Vec<&str> = case["input"]
            .as_array()
            .map(|tokens| tokens.iter().map(|token| token.as_str().unwrap()).collect())
            .unwrap_or_default();
        let input = case["input"]
            .as_str()
            .map_or(PathInput::Tokens(&tokens), PathInput::Scalar);
        let outcome = resolver.resolve(
            input,
            ResolveOptions {
                raise_error: case["raise_error"].as_bool().unwrap(),
                supports_local_path: case["supports_local_path"].as_bool().unwrap(),
            },
        );
        let mut observed = json!({ "current_before": key, "current_after": key });
        let notices = match outcome {
            Ok(result) => {
                observed["result"] = snapshot(&result.element);
                result.notices
            }
            Err(failure) => {
                observed["error"] =
                    json!({ "code": failure.error.code, "message": failure.error.message });
                failure.notices
            }
        };
        observed["warnings"] = json!(
            notices
                .iter()
                .filter(|notice| matches!(notice, PathNotice::ExternalDataSharing))
                .map(PathNotice::message)
                .collect::<Vec<_>>()
        );
        observed["notices"] = json!(
            notices
                .iter()
                .filter(|notice| matches!(notice, PathNotice::LocalFallback(_)))
                .map(PathNotice::message)
                .collect::<Vec<_>>()
        );
        observed["calls"] = json!(*boundary.calls.borrow());
        assert_eq!(observed, case["expected"], "{name}");
        assert!(
            boundary.properties.borrow().is_empty(),
            "{name}: unused properties"
        );
        assert!(
            boundary.local.borrow().is_empty(),
            "{name}: unused local metadata"
        );
        assert!(
            Arc::ptr_eq(resolver.current(), current),
            "{name}: current identity"
        );
        for (key, node) in &nodes {
            assert_eq!(snapshot(node), before[key], "{name}: catalog metadata");
            match (node.parent(), &parents[key]) {
                (Some(left), Some(right)) => {
                    assert!(Arc::ptr_eq(left, right), "{name}: parent identity")
                }
                (None, None) => {}
                _ => panic!("{name}: parent changed"),
            }
        }
    }
}
